// Generated by asset-rules from 3d-review-cli's rules catalog: change the catalog, not this.

/// The rules catalog this was generated from, as written.
pub const CATALOG_TOML: &str = include_str!("../catalogs/3d-review-cli.toml");

/// The rules catalog, read once. `build.rs` checked it, so reading it can't fail.
pub fn catalog() -> &'static ::asset_rules::catalog::Catalog {
    static CATALOG: ::std::sync::OnceLock<::asset_rules::catalog::Catalog> =
        ::std::sync::OnceLock::new();
    CATALOG.get_or_init(|| {
        ::asset_rules::catalog::Catalog::from_toml(CATALOG_TOML).expect("build.rs checked it")
    })
}

/// Every rule in the catalog, in its order.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[allow(clippy::enum_variant_names)]
pub enum RuleId {
    /// `geometry.degenerate_triangles`: Degenerate triangles
    DegenerateTriangles,
    /// `geometry.non_manifold_edges`: Non-manifold edges
    NonManifoldEdges,
    /// `geometry.isolated_vertices`: Loose points
    IsolatedVertices,
    /// `geometry.duplicate_vertices`: Unwelded points
    DuplicateVertices,
    /// `geometry.ngons`: N-gons
    Ngons,
    /// `geometry.missing_normals`: Missing normals
    MissingNormals,
    /// `geometry.missing_tangents`: Missing tangents
    MissingTangents,
    /// `geometry.inverted_normals`: Inside-out faces
    InvertedNormals,
    /// `geometry.hard_edges`: Mostly hard edges
    HardEdges,
    /// `geometry.triangle_budget`: Triangle budget
    TriangleBudget,
    /// `geometry.draw_call_budget`: Draw calls
    DrawCallBudget,
    /// `transform.scale`: Scaled objects
    Scale,
    /// `transform.negative_scale`: Mirrored objects
    NegativeScale,
    /// `transform.unfrozen`: Unfrozen transforms
    Unfrozen,
    /// `transform.pivot_offset`: Off-origin pivot
    PivotOffset,
    /// `scene.unit`: Scene unit
    Unit,
    /// `scene.up_axis`: Up axis
    UpAxis,
    /// `uv.missing`: Missing UVs
    UvMissing,
    /// `uv.out_of_range`: UVs outside 0-1
    UvOutOfRange,
    /// `uv.overlap`: Overlapping UVs
    UvOverlap,
    /// `uv.flipped`: Flipped UVs
    UvFlipped,
    /// `uv.lightmap_missing`: Missing lightmap UVs
    LightmapMissing,
    /// `uv.lightmap_overlap`: Overlapping lightmap UVs
    LightmapOverlap,
    /// `uv.lightmap_padding`: Lightmap padding
    LightmapPadding,
    /// `uv.lightmap_out_of_range`: Lightmap UVs outside 0-1
    LightmapOutOfRange,
    /// `skin.influences`: Too many bone influences
    Influences,
    /// `skin.unnormalized_weights`: Unnormalized weights
    UnnormalizedWeights,
    /// `skin.bones_per_mesh`: Bones per mesh
    BonesPerMesh,
    /// `skin.unused_bones`: Unused bones
    UnusedBones,
    /// `skin.bind_pose_mismatch`: Bind pose differs from the rest pose
    BindPoseMismatch,
    /// `density.texel`: Texel density
    TexelDensity,
    /// `density.triangle_lod`: Needs a LOD
    TriangleLod,
    /// `density.triangle_reduce`: Too dense for its size
    TriangleReduce,
    /// `naming.invalid_characters`: Unsafe characters in names
    InvalidCharacters,
    /// `naming.pattern`: Naming convention
    NamePattern,
    /// `naming.lod_suffix`: LOD names
    LodSuffix,
    /// `naming.collision_prefix`: Orphaned collision
    CollisionPrefix,
    /// `naming.asset_prefix`: Asset prefix
    AssetPrefix,
    /// `hierarchy.empty_nodes`: Empty groups
    EmptyNodes,
    /// `hierarchy.duplicate_names`: Duplicate names
    DuplicateNames,
    /// `hierarchy.multiple_roots`: Several top-level objects
    MultipleRoots,
    /// `hierarchy.lights_cameras`: Lights and cameras
    LightsCameras,
    /// `hierarchy.materials_per_mesh`: Materials per mesh
    MaterialsPerMesh,
}

