/// What one rule's check found.
#[derive(Clone, Debug, PartialEq)]
#[allow(clippy::enum_variant_names, clippy::large_enum_variant)]
pub enum Found {
    DegenerateTriangles(found::DegenerateTriangles),
    NonManifoldEdges(found::NonManifoldEdges),
    IsolatedVertices(found::IsolatedVertices),
    DuplicateVertices(found::DuplicateVertices),
    Ngons(found::Ngons),
    MissingNormals(found::MissingNormals),
    MissingTangents(found::MissingTangents),
    InvertedNormals(found::InvertedNormals),
    HardEdges(found::HardEdges),
    TriangleBudget(found::TriangleBudget),
    DrawCallBudget(found::DrawCallBudget),
    Scale(found::Scale),
    NegativeScale(found::NegativeScale),
    Unfrozen(found::Unfrozen),
    PivotOffset(found::PivotOffset),
    Unit(found::Unit),
    UpAxis(found::UpAxis),
    UvMissing(found::UvMissing),
    UvOutOfRange(found::UvOutOfRange),
    UvOverlap(found::UvOverlap),
    UvFlipped(found::UvFlipped),
    LightmapMissing(found::LightmapMissing),
    LightmapOverlap(found::LightmapOverlap),
    LightmapPadding(found::LightmapPadding),
    LightmapOutOfRange(found::LightmapOutOfRange),
    Influences(found::Influences),
    UnnormalizedWeights(found::UnnormalizedWeights),
    BonesPerMesh(found::BonesPerMesh),
    UnusedBones(found::UnusedBones),
    BindPoseMismatch(found::BindPoseMismatch),
    TexelDensity(found::TexelDensity),
    TriangleLod(found::TriangleLod),
    TriangleReduce(found::TriangleReduce),
    InvalidCharacters(found::InvalidCharacters),
    NamePattern(found::NamePattern),
    LodSuffix(found::LodSuffix),
    CollisionPrefix(found::CollisionPrefix),
    AssetPrefix(found::AssetPrefix),
    EmptyNodes(found::EmptyNodes),
    DuplicateNames(found::DuplicateNames),
    MultipleRoots(found::MultipleRoots),
    LightsCameras(found::LightsCameras),
    MaterialsPerMesh(found::MaterialsPerMesh),
}

